        size[v]++;
    }
    // Print adjacency list
    for(int i = 0; i < n; i++) {
        printf("City %d: ", i + 1);
        for(int j = 0; j < size[i]; j++) {
            printf("%d ", adj[i][j] + 1); // convert back to 1-based
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    int adj[n][n]; // stores neighbors
    int weight[n][n]; // stores weights
    int size[n]; // number of neighbors
    for(int i = 0; i < n; i++) {
        size[i] = 0;
    }
    int u, v, w;
    // Input edges
    for(int i = 0; i < m; i++) {
        scanf("%d %d %d", &u, &v, &w);
        // Convert to 0-based
        u = u - 1;
        v = v - 1;
        // Add edge u -> v
        adj[u][size[u]] = v;
        weight[u][size[u]] = w;
        size[u]++;
        // Add edge v -> u (undirected)
        adj[v][size[v]] = u;
        weight[v][size[v]] = w;
        size[v]++;
    }
    // Print adjacency list
    for(int i = 0; i < n; i++) {
        printf("%d", i + 1);
        for(int j = 0; j < size[i]; j++) {
            printf(" -> (%d, %d)", adj[i][j] + 1, weight[i][j]);
        }
        printf("\n");
    }
    return 0;
}

