    int q;
    scanf("%d", &q);
    while(q--) {
        int n, m;
        int c_lib, c_road;
        scanf("%d %d %d %d", &n, &m, &c_lib, &c_road);
        // Reset arrays
        for(int i = 1; i <= n; i++) {
            size[i] = 0;
            visited[i] = 0;
        }
        // Input roads
        for(int i = 0; i < m; i++) {
            int u, v;
            scanf("%d %d", &u, &v);
            adj[u][size[u]++] = v;
            adj[v][size[v]++] = u;
        }
        int totalCost = 0;
        // If roads are expensive
        if(c_road >= c_lib) {
            totalCost = n * c_lib;
        }
        else {
            // Find connected components
            for(int i = 1; i <= n; i++) {
                if(!visited[i]) {
                    int cities = dfs(i);
                    // 1 library
                    totalCost += c_lib;
                    // roads for remaining cities
                    totalCost += (cities - 1) * c_road;
                }
            }
        }
        printf("%d\n", totalCost);
    }
    return 0;
}

